function normalizeOptions(options) {
  timeouts = {}

  if(options.connectionTimeout !== null && options.connectionTimeout !== undefined) {
    // print deprecation warning
    timeouts.connectionTimeout = options.connectionTimeout
    delete options.connectionTimeout
  }
  .
  .
  .

  return {
      timeouts
  }
}
